  "cadcraft.openFailed": { "zh-CN": "无法在 CADCraft 中打开图纸：{fileName}", en: "Could not open drawing in CADCraft: {fileName}", ja: "CADCraftで図面を開けませんでした: {fileName}", fr: "Impossible d'ouvrir le dessin dans CADCraft : {fileName}", de: "Zeichnung konnte nicht in CADCraft geöffnet werden: {fileName}", es: "No se pudo abrir el dibujo en CADCraft: {fileName}" },
  "filmcraft.editButton": { "zh-CN": "编辑视频", en: "Edit video", ja: "動画を編集", fr: "Modifier la vidéo", de: "Video bearbeiten", es: "Editar video" },
  "filmcraft.licenseButton": { "zh-CN": "FilmCraft 许可", en: "FilmCraft license", ja: "ライセンス", fr: "Licence FilmCraft", de: "FilmCraft-Lizenz", es: "Licencia de FilmCraft" },
  "filmcraft.licenseTitle": { "zh-CN": "FilmCraft 许可与致谢", en: "FilmCraft license and credits", ja: "FilmCraftのライセンスとクレジット", fr: "Licence et crédits FilmCraft", de: "FilmCraft-Lizenz und Credits", es: "Licencia y créditos de FilmCraft" },
  "filmcraft.licenseSummary": { "zh-CN": "FilmCraft 由 ArtCraft Team 和贡献者开发，采用 MIT 或 Apache License 2.0 双重许可。品牌标志有单独的使用条款。", en: "FilmCraft is developed by the ArtCraft Team and contributors, dual-licensed under MIT or Apache License 2.0. Brand marks have separate terms.", ja: "FilmCraftはArtCraft Teamとコントリビューターが開発し、MIT LicenseまたはApache License 2.0で提供されています。ブランドマークには別の利用条件があります。", fr: "FilmCraft est développé par l'équipe ArtCraft et ses contributeurs, sous licence MIT ou Apache 2.0. Les marques ont des conditions distinctes.", de: "FilmCraft wird vom ArtCraft-Team und Mitwirkenden unter MIT oder Apache 2.0 veröffentlicht. Für Marken gelten gesonderte Bedingungen.", es: "FilmCraft es desarrollado por ArtCraft Team y colaboradores, bajo MIT o Apache 2.0. Las marcas tienen condiciones independientes." },
  "filmcraft.mindzjChangesTitle": { "zh-CN": "WorkspaceWeb 集成", en: "WorkspaceWeb integration", ja: "WorkspaceWebとの連携", fr: "Intégration WorkspaceWeb", de: "WorkspaceWeb-Integration", es: "Integración con WorkspaceWeb" },
  "filmcraft.mindzjChanges": { "zh-CN": "WorkspaceWeb 将选中的 Vault 视频发送到 FilmCraft。FilmCraft 项目和导出视频会保存到源视频所在文件夹；源视频保持不变。", en: "WorkspaceWeb sends the selected Vault video to FilmCraft. FilmCraft projects and exported videos are saved beside the source; the source video stays unchanged.", ja: "Vaultで選択した動画をFilmCraftに渡します。FilmCraftのプロジェクトと書き出した動画は元動画と同じフォルダーに保存し、元動画は変更しません。", fr: "WorkspaceWeb envoie la vidéo sélectionnée du coffre à FilmCraft. Les projets et vidéos exportées sont enregistrés à côté de la source, qui reste inchangée.", de: "WorkspaceWeb übergibt das ausgewählte Vault-Video an FilmCraft. Projekte und Exporte werden neben der Quelldatei gespeichert; das Original bleibt unverändert.", es: "WorkspaceWeb envía el video seleccionado del Vault a FilmCraft. Los proyectos y videos exportados se guardan junto al original, que permanece sin cambios." },
  "filmcraft.upstreamLink": { "zh-CN": "FilmCraft 项目", en: "FilmCraft project", ja: "FilmCraft公式プロジェクト", fr: "Projet FilmCraft", de: "FilmCraft-Projekt", es: "Proyecto FilmCraft" },
