  "settings.aboutDescription": { "zh-CN": "MindZJ 是一款 AI 原生、CLI 友好的开源离线笔记软件，灵感来自 Obsidian。支持 Markdown 编辑、双向链接、知识图谱、全文搜索、每日笔记、模板系统等功能。跨平台支持 Windows、macOS、Linux、iOS 和 Android。", en: "MindZJ is an AI-native, CLI-friendly open-source offline note app inspired by Obsidian. It supports Markdown editing, backlinks, knowledge graphs, full-text search, daily notes, templates, and more. It runs across Windows, macOS, Linux, iOS, and Android.", ja: "MindZJ は Obsidian に着想を得た、AI ネイティブで CLI フレンドリーなオープンソースのオフラインノートアプリです。Markdown 編集、バックリンク、知識グラフ、全文検索、デイリーノート、テンプレートなどに対応し、Windows、macOS、Linux、iOS、Android で動作します。", fr: "MindZJ est une application de notes hors ligne open source, native pour l’IA et pensée pour le CLI, inspirée d’Obsidian. Elle prend en charge l’édition Markdown, les backlinks, les graphes de connaissances, la recherche plein texte, les notes quotidiennes, les modèles, et plus encore. Elle fonctionne sur Windows, macOS, Linux, iOS et Android.", de: "MindZJ ist eine KI-native, CLI-freundliche Open-Source-App für Offline-Notizen, inspiriert von Obsidian. Sie unterstützt Markdown-Bearbeitung, Backlinks, Wissensgraphen, Volltextsuche, tägliche Notizen, Vorlagen und mehr. Sie läuft auf Windows, macOS, Linux, iOS und Android.", es: "MindZJ es una app de notas offline de código abierto, nativa para IA y orientada a CLI, inspirada en Obsidian. Admite edición Markdown, backlinks, grafos de conocimiento, búsqueda de texto completo, notas diarias, plantillas y más. Funciona en Windows, macOS, Linux, iOS y Android." },
  "settings.webAboutTitle": { "zh-CN": "WorkspaceWeb", en: "WorkspaceWeb", ja: "WorkspaceWeb", fr: "WorkspaceWeb", de: "WorkspaceWeb", es: "WorkspaceWeb" },
  "settings.webAboutDescription": { "zh-CN": "WorkspaceWeb 是面向浏览器的工作空间。通过 Web 浏览器访问和编辑服务器上的 Markdown Vault，并管理图片、PDF 和其他资源。", en: "WorkspaceWeb is a browser-based workspace for accessing and editing a server-side Markdown Vault and managing images, PDFs, and other resources.", ja: "WorkspaceWebは、ブラウザーからサーバー上のMarkdown Vaultにアクセスして編集し、画像、PDF、その他のリソースを管理できるワークスペースです。", fr: "WorkspaceWeb est un espace de travail dans le navigateur pour accéder à un Vault Markdown sur serveur, le modifier et gérer des images, des PDF et d’autres ressources.", de: "WorkspaceWeb ist ein browserbasierter Arbeitsbereich zum Zugriff auf und Bearbeiten eines serverseitigen Markdown-Vaults sowie zur Verwaltung von Bildern, PDFs und anderen Ressourcen.", es: "WorkspaceWeb es un espacio de trabajo en el navegador para acceder y editar un Vault Markdown en el servidor y administrar imágenes, PDF y otros recursos." },
  "settings.webAboutTagline": { "zh-CN": "浏览器访问 · 服务器 Vault · SolidJS + Rust", en: "Browser access · Server-side Vault · SolidJS + Rust", ja: "ブラウザーアクセス · サーバーVault · SolidJS + Rust", fr: "Accès navigateur · Vault serveur · SolidJS + Rust", de: "Browserzugriff · Server-Vault · SolidJS + Rust", es: "Acceso desde navegador · Vault en servidor · SolidJS + Rust" },
  "settings.webDocumentation": { "zh-CN": "Web版文档", en: "Web documentation", ja: "Web版ドキュメント", fr: "Documentation Web", de: "Web-Dokumentation", es: "Documentación Web" },
  "settings.aboutTagline": { "zh-CN": "AI 原生 · CLI 优先 · 开源离线笔记系统", en: "AI-native · CLI-first · Open-source offline notes", ja: "AI ネイティブ · CLI ファースト · オープンソースのオフラインノート", fr: "Natif IA · CLI d’abord · Notes hors-ligne open source", de: "KI-nativ · CLI-first · Quelloffene Offline-Notizen", es: "Nativo para IA · CLI primero · Notas offline open source" },
  "settings.support": { "zh-CN": "支持开源项目作者", en: "Support the developer", ja: "開発者を応援する", fr: "Soutenir le développeur", de: "Entwickler unterstützen", es: "Apoyar al desarrollador" },
  "settings.supportMessage": { "zh-CN": "如果 MindZJ 对你有帮助，欢迎请作者喝杯咖啡 ☕", en: "If MindZJ is useful to you, consider buying the author a coffee ☕", ja: "MindZJ が役に立ったら、ぜひ作者にコーヒーをおごってください ☕", fr: "Si MindZJ vous est utile, offrez un café à l’auteur ☕", de: "Wenn MindZJ dir hilft, spendiere dem Autor doch einen Kaffee ☕", es: "Si MindZJ te resulta útil, invita un café al autor ☕" },
