  "settings.feature.local": { "zh-CN": "本地优先 · 纯 Markdown 存储", en: "Local first · pure Markdown storage", ja: "ローカルファースト · 純粋な Markdown 保存", fr: "Local d’abord · stockage Markdown pur", de: "Lokal zuerst · reiner Markdown-Speicher", es: "Local primero · almacenamiento Markdown puro" },
  "settings.feature.ai": { "zh-CN": "AI 原生 · 本地模型与 API Key 模型集成", en: "AI-native · local and API-key model integration", ja: "AI ネイティブ · ローカルモデルと API キーモデルの統合", fr: "Natif IA · intégration de modèles locaux et à clé API", de: "KI-nativ · Integration lokaler Modelle und API-Schlüssel-Modelle", es: "Nativo para IA · integración de modelos locales y con clave API" },
