  "settings.feature.tauri": { "zh-CN": "轻量级 · Tauri 2.0 (~10MB)", en: "Lightweight · Tauri 2.0 (~10 MB)", ja: "軽量 · Tauri 2.0 (~10 MB)", fr: "Léger · Tauri 2.0 (~10 Mo)", de: "Leichtgewichtig · Tauri 2.0 (~10 MB)", es: "Ligero · Tauri 2.0 (~10 MB)" },
  "settings.feature.crossPlatform": { "zh-CN": "跨平台 · Windows / macOS / Linux / iOS / Android", en: "Cross-platform · Windows / macOS / Linux / iOS / Android", ja: "クロスプラットフォーム · Windows / macOS / Linux / iOS / Android", fr: "Multiplateforme · Windows / macOS / Linux / iOS / Android", de: "Plattformübergreifend · Windows / macOS / Linux / iOS / Android", es: "Multiplataforma · Windows / macOS / Linux / iOS / Android" },
  "settings.thanks": { "zh-CN": "感谢", en: "Acknowledgements", ja: "謝辞", fr: "Remerciements", de: "Danksagungen", es: "Agradecimientos" },
  "settings.thanksMessage": { "zh-CN": "感谢 Obsidian 社区的灵感与开源生态，以及 Tauri、SolidJS、CodeMirror、tantivy 等开源项目的杰出工作。", en: "Thanks to the Obsidian community for the inspiration and open ecosystem, and to the Tauri, SolidJS, CodeMirror and tantivy projects for their outstanding work.", ja: "インスピレーションとオープンなエコシステムを提供してくれた Obsidian コミュニティ、そして Tauri、SolidJS、CodeMirror、tantivy などのオープンソースプロジェクトに感謝します。", fr: "Merci à la communauté Obsidian pour son inspiration et son écosystème ouvert, ainsi qu’aux projets Tauri, SolidJS, CodeMirror et tantivy pour leur travail remarquable.", de: "Dank an die Obsidian-Community für Inspiration und offenes Ökosystem sowie an die Projekte Tauri, SolidJS, CodeMirror und tantivy für ihre hervorragende Arbeit.", es: "Gracias a la comunidad de Obsidian por la inspiración y al ecosistema abierto, así como a los proyectos Tauri, SolidJS, CodeMirror y tantivy por su excelente trabajo." },
