  "settings.markerColors": { "zh-CN": "彩色标记颜色", en: "Marker colors", ja: "マーカー色", fr: "Couleurs de marqueur", de: "Markerfarben", es: "Colores de marcador" },
  "settings.markerColorsDescription": { "zh-CN": "设置 Markdown 工具栏标记重点使用的 7 个颜色", en: "Set the 7 colors used by the Markdown toolbar marker", ja: "Markdown ツールバーのマーカーで使う 7 色を設定します", fr: "Définir les 7 couleurs utilisées par le marqueur de la barre Markdown", de: "Die 7 Farben für den Markdown-Werkzeugleistenmarker festlegen", es: "Configura los 7 colores usados por el marcador de la barra Markdown" },
