  "settings.showLineNumbersDescription": { "zh-CN": "在编辑器左侧显示行号", en: "Show line numbers on the left side of the editor", ja: "エディター左側に行番号を表示", fr: "Afficher les numéros de ligne à gauche de l’éditeur", de: "Zeilennummern links im Editor anzeigen", es: "Mostrar números de línea a la izquierda del editor" },
  "settings.codeBlockLineNumbers": { "zh-CN": "代码块行号", en: "Code block line numbers", ja: "コードブロックの行番号", fr: "Numéros de ligne des blocs de code", de: "Zeilennummern in Codeblöcken", es: "Números de línea en bloques de código" },
  "settings.codeBlockLineNumbersDescription": { "zh-CN": "在 Markdown 代码块内显示行号，默认隐藏", en: "Show line numbers inside Markdown code blocks. Hidden by default.", ja: "Markdown のコードブロック内に行番号を表示します。既定では非表示です。", fr: "Afficher les numéros de ligne dans les blocs de code Markdown. Masqués par défaut.", de: "Zeilennummern in Markdown-Codeblöcken anzeigen. Standardmäßig ausgeblendet.", es: "Muestra números de línea dentro de los bloques de código Markdown. Ocultos por defecto." },
  "settings.wordWrap": { "zh-CN": "自动换行", en: "Word wrap", ja: "自動折り返し", fr: "Retour à la ligne automatique", de: "Zeilenumbruch", es: "Ajuste de línea" },
