  "settings.readableLineLengthDescription": { "zh-CN": "限制编辑器最大行宽，提升阅读体验", en: "Limit editor line width for better readability", ja: "読みやすさのために最大行幅を制限", fr: "Limiter la largeur des lignes pour améliorer la lecture", de: "Maximale Zeilenbreite für bessere Lesbarkeit begrenzen", es: "Limitar el ancho de línea para mejorar la lectura" },
  "settings.spellCheck": { "zh-CN": "拼写检查", en: "Spell check", ja: "スペルチェック", fr: "Correction orthographique", de: "Rechtschreibprüfung", es: "Corrector ortográfico" },
  "settings.spellCheckDescription": { "zh-CN": "启用浏览器拼写检查", en: "Enable browser spell checking", ja: "ブラウザーのスペルチェックを有効化", fr: "Activer la correction orthographique du navigateur", de: "Browser-Rechtschreibprüfung aktivieren", es: "Activar la corrección ortográfica del navegador" },
  "settings.autoSaveInterval": { "zh-CN": "自动保存间隔 (ms)", en: "Auto-save interval (ms)", ja: "自動保存間隔 (ms)", fr: "Intervalle d’enregistrement auto (ms)", de: "Auto-Speicherintervall (ms)", es: "Intervalo de guardado automático (ms)" },
  "settings.autoSaveIntervalDescription": { "zh-CN": "编辑后自动保存的延迟时间", en: "Delay before auto-saving after edits", ja: "編集後に自動保存するまでの遅延", fr: "Délai avant l’enregistrement automatique après modification", de: "Verzögerung bis zum automatischen Speichern nach Änderungen", es: "Retraso antes de guardar automáticamente tras editar" },
  "settings.autoSaveEnabled": { "zh-CN": "启用自动保存", en: "Enable auto-save", ja: "自動保存を有効にする", fr: "Activer l’enregistrement automatique", de: "Automatisches Speichern aktivieren", es: "Activar guardado automático" },
  "settings.autoSaveEnabledDescription": { "zh-CN": "默认关闭。关闭时请使用保存按钮或 Ctrl+S", en: "Off by default. When off, use Save or Ctrl+S", ja: "既定ではオフです。オフの場合は保存ボタンまたは Ctrl+S を使います", fr: "Désactivé par défaut. Utilisez Enregistrer ou Ctrl+S lorsqu’il est désactivé", de: "Standardmäßig aus. Verwenden Sie Speichern oder Strg+S, wenn es aus ist", es: "Desactivado por defecto. Usa Guardar o Ctrl+S cuando esté desactivado" },
  "editLock.held": { "zh-CN": "此笔记正在由 {owner} 编辑。请确认对方是否仍在编辑。", en: "{owner} is editing this note. Check whether they are still editing.", ja: "このノートは {owner} が編集中です。まだ編集しているか確認してください。", fr: "{owner} modifie cette note. Vérifiez si la personne est toujours active.", de: "{owner} bearbeitet diese Notiz. Prüfen Sie, ob die Person noch aktiv ist.", es: "{owner} está editando esta nota. Comprueba si sigue activo." },
  "editLock.lost": { "zh-CN": "其他用户接管了此笔记的编辑权。当前标签页中的未保存内容仍保留，请复制保存后再关闭。", en: "Another user took over this note. Unsaved text remains in this tab; copy it somewhere safe before closing.", ja: "他のユーザーに編集権が引き継がれました。このタブの未保存内容は残っています。閉じる前にコピーして保存してください。", fr: "Un autre utilisateur a repris cette note. Le texte non enregistré reste dans cet onglet ; copiez-le avant de fermer.", de: "Eine andere Person hat die Bearbeitung übernommen. Ungespeicherter Text bleibt in diesem Tab; kopieren Sie ihn vor dem Schließen.", es: "Otro usuario tomó el control. El texto sin guardar sigue en esta pestaña; cópialo antes de cerrar." },
  "editLock.checkAgain": { "zh-CN": "再次确认（{count}/3）", en: "Check again ({count}/3)", ja: "再確認する（{count}/3）", fr: "Revérifier ({count}/3)", de: "Erneut prüfen ({count}/3)", es: "Volver a comprobar ({count}/3)" },
  "editLock.keepReading": { "zh-CN": "继续查看", en: "Keep viewing", ja: "閲覧を続ける", fr: "Continuer à consulter", de: "Weiter ansehen", es: "Seguir viendo" },
  "editLock.takeoverWarning": { "zh-CN": "仍由 {owner} 持有编辑权。接管后，对方尚未保存的修改可能无法保存。确定接管吗？", en: "{owner} still holds the edit lock. Taking over may prevent their unsaved changes from being saved. Take over?", ja: "現在も {owner} が編集権を持っています。接管すると、相手の未保存の変更が保存できなくなる可能性があります。接管しますか？", fr: "{owner} détient toujours le verrou. La reprise peut empêcher l’enregistrement de ses modifications. Reprendre ?", de: "{owner} hält weiterhin die Sperre. Eine Übernahme kann das Speichern der Änderungen verhindern. Übernehmen?", es: "{owner} aún tiene el bloqueo. Al tomarlo, quizá no pueda guardar sus cambios. ¿Tomarlo?" },
  "editLock.takeover": { "zh-CN": "接管编辑权", en: "Take over editing", ja: "編集権を引き継ぐ", fr: "Reprendre la modification", de: "Bearbeitung übernehmen", es: "Tomar el control de edición" },
  "editLock.unsavedChanges": { "zh-CN": "此笔记有未保存的更改。现在保存吗？", en: "This note has unsaved changes. Save them now?", ja: "このノートには未保存の変更があります。保存しますか？", fr: "Cette note contient des modifications non enregistrées. Les enregistrer ?", de: "Diese Notiz enthält ungespeicherte Änderungen. Jetzt speichern?", es: "Esta nota tiene cambios sin guardar. ¿Guardarlos ahora?" },
  "editLock.saveChanges": { "zh-CN": "保存更改", en: "Save changes", ja: "変更を保存", fr: "Enregistrer", de: "Änderungen speichern", es: "Guardar cambios" },
  "editLock.stayEditing": { "zh-CN": "继续编辑", en: "Stay editing", ja: "編集を続ける", fr: "Continuer à modifier", de: "Weiter bearbeiten", es: "Seguir editando" },
  "settings.defaultViewMode": { "zh-CN": "默认视图模式", en: "Default view mode", ja: "既定の表示モード", fr: "Mode d’affichage par défaut", de: "Standard-Ansichtsmodus", es: "Modo de vista predeterminado" },
  "settings.defaultViewModeDescription": { "zh-CN": "新打开文件的默认显示模式", en: "Default mode for newly opened files", ja: "新しく開いたファイルの既定モード", fr: "Mode par défaut des fichiers nouvellement ouverts", de: "Standardmodus für neu geöffnete Dateien", es: "Modo predeterminado para archivos recién abiertos" },
